 const slozeneContent=[
  {title:'Obsah trojúhelníku u žebříku',story:['Žebřík dlouhý 13 metrů je opřený o svislou zeď; jeho dolní konec je od zdi vzdálen 5 metrů.','Žebřík, zeď a zem ohraničují pravoúhlý trojúhelník.'],question:'Kolik metrů čtverečních má tento pravoúhlý trojúhelník?',other:'Do jaké výšky na zdi žebřík dosahuje?',paths:['Nejprve Pythagorovou větou najdu výšku √(13² − 5²) = 12 m, a potom obsah trojúhelníku 5 × 12 ÷ 2.','Vypočítám výšku a obsah jako dva samostatné kroky ve stejném pořadí.','Obsah vypočítám přímo jako 13 × 5 ÷ 2, bez hledání výšky.'],valid:[0,1],explain:['Výška je √(169 − 25) = 12 m; obsah je 5 × 12 ÷ 2 = 30 m².','Postupné kroky vedou ke stejnému výsledku 30 m².','Ve vzorci pro obsah trojúhelníku patří k základně kolmá výška, ne přepona (žebřík) samotná.'],answer:30,unit:'m²',check:'Odvěsny 5 m a 12 m tvoří pravoúhlý trojúhelník s přeponou 13 m; jejich součin dělený dvěma je 30 m².',badcheck:'Výsledek je správný, pokud je roven délce žebříku.',model:'Úloha má dva kroky: nejprve Pythagorovou větou najdeme chybějící odvěsnu, potom teprve počítáme obsah trojúhelníku.',modelChoice:{q:'Kterou veličinu musíme zjistit jako první?',a:['Chybějící odvěsnu (výšku).','Rovnou obsah trojúhelníku.'],ok:0},practice:{q:'Který postup respektuje správné pořadí kroků?',a:['Nejprve Pythagorova věta, potom vzorec pro obsah.','Rovnou 13 × 5 ÷ 2.'],ok:0}},
  {title:'Původní mzda před zvýšením',story:['Po zvýšení o 8 % je měsíční mzda zaměstnance 27 000 Kč.','Zvýšení se počítalo z původní mzdy.'],question:'Kolik korun činila původní mzda?',other:'Kolik korun bylo samotné zvýšení?',paths:['Uvědomím si, že 27 000 Kč představuje 108 % původní mzdy, a vydělím 1,08.','Sestavím rovnici 1,08x = 27 000 a vyřeším ji pro x.','Odečtu 8 % z nové mzdy 27 000 Kč.'],valid:[0,1],explain:['Původní mzda je 27 000 ÷ 1,08 = 25 000 Kč.','Řešením rovnice 1,08x = 27 000 vyjde stejných x = 25 000.','Osm procent se počítalo z původní mzdy, nikoli z nové; odečtení z nové mzdy dá špatný výsledek.'],answer:25000,unit:'Kč',check:'Osm procent z 25 000 Kč je 2 000 Kč, a po přičtení k původní mzdě vznikne přesně 27 000 Kč.',badcheck:'Stačí, když je původní mzda nižší než 27 000 Kč.',model:'Nová mzda představuje původních 100 % plus zvýšení 8 %, dohromady 108 %; úlohu lze zapsat i jako rovnici 1,08x = 27 000.',modelChoice:{q:'Kolik procent původní mzdy představuje nová mzda 27 000 Kč?',a:['108 %','92 %'],ok:0},practice:{q:'Která rovnice odpovídá zadání?',a:['1,08x = 27 000','0,92x = 27 000'],ok:0}},
  {title:'Hrana krychlové nádrže',story:['Krychlová nádrž má objem 512 litrů.','Chceme zjistit délku její hrany v decimetrech (1 litr = 1 dm³).'],question:'Kolik decimetrů měří hrana nádrže?',other:'Kolik decimetrů čtverečních má jedna stěna nádrže?',paths:['Objem v litrech je zároveň objem v dm³; hranu najdu jako třetí odmocninu z 512.','Postupně zkouším celé hrany: 7³ = 343, 8³ = 512.','Objem 512 vydělím třemi, protože krychle má tři rozměry.'],valid:[0,1],explain:['Hrana je ∛512 = 8 dm.','Osmička je první číslo, jehož třetí mocnina dá přesně 512.','Třetí mocnina se neruší dělením třemi; potřebujeme třetí odmocninu.'],answer:8,unit:'dm',check:'Krychle s hranou 8 dm má objem 8³ = 512 dm³, tedy 512 litrů.',badcheck:'Výsledek je správný, pokud po vynásobení třemi dostaneme méně než 512.',model:'Úloha nejprve převede litry na dm³ (jsou to stejné jednotky), a potom hledá hranu jako třetí odmocninu objemu.',modelChoice:{q:'Kolik dm³ odpovídá 512 litrům?',a:['512 dm³, protože litr a dm³ jsou stejná jednotka.','5,12 dm³.'],ok:0},practice:{q:'Která rovnice popisuje zadaný objem?',a:['a³ = 512','3a = 512'],ok:0}},
  {title:'Omezený kruhový záhon',story:['Kruhový záhon má poloměr r metrů a jeho obsah nesmí přesáhnout 50 metrů čtverečních kvůli velikosti zahrady.','Pro výpočet použij π = 3,14.'],question:'Jaký je největší celý poloměr v metrech, který tuto podmínku ještě splňuje?',other:'Jaký obsah by měl záhon při tomto největším poloměru?',paths:['Sestavím nerovnici 3,14r² ≤ 50 a najdu největší celé řešení.','Vydělím 50 číslem 3,14, odmocním výsledek a zaokrouhlím dolů.','Vydělím 50 číslem 3,14 a zaokrouhlím nahoru.'],valid:[0,1],explain:['Nerovnice dá r² ≤ 15,92…, tedy r ≤ 3,99…; největší celé řešení je 3.','Odmocnina z 15,92 je přibližně 3,99; zaokrouhlením dolů dostaneme 3 m.','Zaokrouhlení nahoru na 4 m by dalo obsah 3,14 × 16 = 50,24 m², což už podmínku porušuje.'],answer:3,unit:'m',check:'Pro poloměr 3 m je obsah 3,14 × 9 = 28,26 m², což splňuje podmínku; pro poloměr 4 m by obsah 50,24 m² už limit překročil.',badcheck:'Výsledek je správný, pokud je menší než 50.',model:'Úloha spojuje vzorec pro obsah kruhu s řešením nerovnice a zaokrouhlením na celé metry dolů.',modelChoice:{q:'Proč zaokrouhlujeme výsledek dolů, a ne nahoru?',a:['Protože zaokrouhlení nahoru by překročilo povolený obsah.','Protože poloměr se vždy zaokrouhluje dolů.'],ok:0},practice:{q:'Která nerovnice odpovídá zadání?',a:['3,14r² ≤ 50','3,14r² ≥ 50'],ok:0}},
  {title:'Žáci s dobrou známkou',story:['Ve třídě s 25 žáky napsalo test na jedničku nebo dvojku 60 % žáků.','Zbylí žáci dostali horší známku.'],question:'Kolik žáků napsalo test na jedničku nebo dvojku?',other:'Kolik žáků dostalo horší známku než dvojku?',paths:['Vypočítám 60 % z 25 žáků.','Zjistím 10 % a 50 % z 25 žáků a obě části sečtu.','Vydělím 25 žáků číslem 60.'],valid:[0,1],explain:['Výpočet 0,6 × 25 = 15 žáků.','Padesát procent je 12,5 žáka a deset procent je 2,5 žáka; jejich součet je 15 žáků.','Dělení 25 ÷ 60 by hledalo úplně jinou veličinu, ne šedesátiprocentní podíl.'],answer:15,unit:'žáků',check:'Patnáct žáků z 25 je přesně 60 %, protože 15 ÷ 25 = 0,6.',badcheck:'Výsledek je správný, pokud je menší než celkový počet žáků.',model:'Nejprve musíme z procentního podílu a celkového počtu žáků zjistit skutečný počet, teprve potom lze porovnávat zbylé žáky.',modelChoice:{q:'Který počet je v této úloze procentním základem?',a:['Všech 25 žáků třídy.','Jen žáci s jedničkou nebo dvojkou.'],ok:0},practice:{q:'Který výpočet určí počet žáků s lepší známkou?',a:['0,6 × 25','25 ÷ 0,6'],ok:0}},
  {title:'Povrch hranolu s pravoúhlou podstavou',story:['Trojboký hranol má podstavu ve tvaru pravoúhlého trojúhelníku s odvěsnami 6 cm a 8 cm.','Výška (délka) hranolu je 15 centimetrů.'],question:'Kolik centimetrů čtverečních měří povrch hranolu?',other:'Kolik centimetrů krychlových měří objem hranolu?',paths:['Nejprve Pythagorovou větou najdu přeponu podstavy √(6² + 8²) = 10 cm, potom obvod a obsah podstavy, a dosadím do vzorce pro povrch hranolu.','Postupně spočítám přeponu, obvod podstavy 24 cm, obsah podstavy 24 cm² a povrch 2×24 + 24×15.','Povrch vypočítám jako součin obsahu podstavy a výšky hranolu.'],valid:[0,1],explain:['Přepona je 10 cm, obvod podstavy 24 cm, obsah podstavy 24 cm²; povrch je 2×24 + 24×15 = 48 + 360 = 408 cm².','Postupné kroky vedou ke stejnému výsledku 408 cm².','Součin obsahu podstavy a výšky je objem tělesa, ne jeho povrch.'],answer:408,unit:'cm²',check:'Povrch 408 cm² se skládá ze dvou podstav po 24 cm² a bočních stěn o obsahu 360 cm² (obvod 24 cm krát výška 15 cm).',badcheck:'Výsledek je správný, pokud je roven objemu hranolu.',model:'Úloha nejprve vyžaduje Pythagorovu větu na zjištění přepony podstavy, teprve potom lze počítat obvod, obsah podstavy a celý povrch hranolu.',modelChoice:{q:'Kterou veličinu musíme zjistit úplně první?',a:['Přeponu trojúhelníkové podstavy.','Rovnou povrch hranolu.'],ok:0},practice:{q:'Jaký je obvod podstavy hranolu?',a:['6 + 8 + 10 = 24 cm','6 + 8 = 14 cm'],ok:0}},
  {title:'Kapesné na samolepky',story:['Kapesné 600 Kč chce Klára rozdělit tak, aby jí po nákupu zůstalo alespoň 20 % z celé částky.','Chce koupit co nejvíce stejných samolepek po 25 Kč.'],question:'Kolik nejvíce samolepek si Klára může koupit?',other:'Kolik korun jí musí po nákupu minimálně zůstat?',paths:['Nejprve vypočítám, kolik korun představuje 20 % z 600 Kč, a potom sestavím nerovnici 25x ≤ 600 − 120.','Zjistím povinnou rezervu 120 Kč, zbytek 480 Kč vydělím cenou samolepky a zaokrouhlím dolů.','Rovnou vydělím celých 600 Kč cenou samolepky 25 Kč bez odečtení rezervy.'],valid:[0,1],explain:['Rezerva je 0,2 × 600 = 120 Kč; nerovnice 25x ≤ 480 dá x ≤ 19,2, tedy nejvíce 19 samolepek.','Po odečtení rezervy zbývá 480 Kč; 480 ÷ 25 = 19,2, zaokrouhleno dolů na 19.','Bez odečtení dvacetiprocentní rezervy bychom povolili útratu celých 600 Kč, což porušuje podmínku o zbylých penězích.'],answer:19,unit:'samolepek',check:'Devatenáct samolepek stojí 475 Kč a z 600 Kč zbude 125 Kč, což je více než požadovaných 120 Kč (20 %).',badcheck:'Stačí, když je počet samolepek menší než 600 ÷ 25.',model:'Úloha nejprve spojuje procenta (výpočet povinné rezervy) a potom nerovnici pro největší možný počet kusů.',modelChoice:{q:'Kolik korun představuje povinná rezerva 20 % z 600 Kč?',a:['120 Kč.','20 Kč.'],ok:0},practice:{q:'Která nerovnice odpovídá zadání po odečtení rezervy?',a:['25x ≤ 480','25x ≤ 600'],ok:0}},
  {title:'Obsah lichoběžníkové zahrady',story:['Lichoběžníková zahrada má kratší základnu x metrů a delší základnu (x + 6) metrů.','Výška mezi základnami je 8 metrů a pro x = 10 chceme znát obsah zahrady.'],question:'Kolik metrů čtverečních má zahrada pro x = 10?',other:'Jak dlouhá je delší základna pro x = 10?',paths:['Sestavím výraz pro obsah (x + (x + 6)) ÷ 2 × 8, zjednoduším na (2x + 6) × 4, a dosadím x = 10.','Dosadím x = 10 do rozměrů, spočítám obě základny a poté obsah podle vzorce pro lichoběžník.','Sečtu jen obě základny bez použití výšky: x + (x + 6).'],valid:[0,1],explain:['Zjednodušený výraz (2×10 + 6) × 4 = 26 × 4 = 104 m².','Základny jsou 10 m a 16 m; obsah je (10+16)÷2×8 = 13×8 = 104 m², stejný výsledek.','Obsah lichoběžníku vyžaduje i výšku; bez ní bychom získali jen součet základen, ne obsah.'],answer:104,unit:'m²',check:'Průměrná délka základen 13 m krát výška 8 m dá stejných 104 m².',badcheck:'Výsledek je správný, pokud je roven součtu obou základen.',model:'Obsah lichoběžníku je průměrná délka základen krát výška; nejprve výraz zjednodušíme, potom dosadíme x = 10.',modelChoice:{q:'Které dvě délky se ve vzorci pro obsah lichoběžníku průměrují?',a:['Obě základny.','Základna a výška.'],ok:0},practice:{q:'Který výraz je zjednodušeným zápisem obsahu?',a:['(2x + 6) × 4','2x + 6'],ok:0}},
  {title:'Poloměr většího hřiště',story:['Obvod kruhového hřiště R je o 12,56 metru delší než obvod menšího kruhu s poloměrem 5 metrů.','Pro výpočet použij π = 3,14.'],question:'Kolik metrů měří poloměr většího hřiště?',other:'Kolik metrů měří obvod menšího kruhu?',paths:['Sestavím rovnici 2πR = 2π×5 + 12,56 a vyřeším ji pro R.','Nejprve vypočítám obvod menšího kruhu 31,4 m, přičtu 12,56 m a získaný obvod vydělím 2π.','Rozdíl 12,56 m vydělím přímo poloměrem 5 m.'],valid:[0,1],explain:['Rovnice se upraví na 6,28R = 43,96, tedy R = 7 m.','Obvod menšího kruhu je 31,4 m; po přičtení 12,56 m dostaneme 43,96 m, což po vydělení 6,28 dá stejných R = 7 m.','Rozdíl obvodů nesouvisí přímo s poloměrem menšího kruhu tímto dělením; vede k nesprávnému výsledku.'],answer:7,unit:'m',check:'Obvod hřiště s poloměrem 7 m je 2 × 3,14 × 7 = 43,96 m, což je o 12,56 m více než obvod 31,4 m menšího kruhu.',badcheck:'Stačí, když je výsledek větší než 5 m.',model:'Úloha spojuje vzorec pro obvod kruhu s řešením rovnice o jedné neznámé R.',modelChoice:{q:'Jaký obvod má menší kruh s poloměrem 5 m?',a:['31,4 m.','15,7 m.'],ok:0},practice:{q:'Která rovnice odpovídá zadání?',a:['2×3,14×R = 2×3,14×5 + 12,56','3,14×R = 12,56'],ok:0}},
  {title:'Splátka půjčky',story:['Michal si půjčil 12 000 Kč a splácí ji rovnými měsíčními splátkami.','Po 5 měsících splácení mu zbývá doplatit ještě 40 % z původní půjčky.'],question:'Kolik korun činí jedna měsíční splátka?',other:'Kolik korun ještě Michal celkem dluží?',paths:['Nejprve zjistím, kolik korun představuje splacených 60 % půjčky, a tuto částku vydělím pěti měsíci.','Vypočítám 60 % z 12 000 Kč (7 200 Kč) a vydělím ji počtem měsíců 5.','Vydělím celou půjčku 12 000 Kč pěti měsíci bez ohledu na to, kolik procent už bylo splaceno.'],valid:[0,1],explain:['Splaceno je 60 % z 12 000 Kč, tedy 7 200 Kč; jedna splátka je 7 200 ÷ 5 = 1 440 Kč.','Postup krok za krokem vede ke stejnému výsledku 1 440 Kč.','Dělení celé půjčky pěti měsíci by předpokládalo, že po pěti měsících je splaceno vše, což zadání neříká.'],answer:1440,unit:'Kč',check:'Pět splátek po 1 440 Kč dá dohromady 7 200 Kč, což je přesně 60 % z půjčky 12 000 Kč.',badcheck:'Stačí, když je splátka menší než 12 000 Kč.',model:'Úloha nejprve pomocí procent zjistí, kolik už bylo splaceno, a teprve potom tuto částku rozdělí na jednotlivé měsíční splátky.',modelChoice:{q:'Kolik procent půjčky bylo po pěti měsících splaceno?',a:['60 %, protože zbývá doplatit 40 %.','40 %.'],ok:0},practice:{q:'Který výpočet určí jednu splátku?',a:['(0,6 × 12 000) ÷ 5','12 000 ÷ 5'],ok:0}}
 ];
 const contentByTopic={mocniny:mocninyContent,vyrazy:vyrazyContent,rovnice:rovniceContent,nerovnice:nerovniceContent,pythagoras:pythagorasContent,kruh:kruhContent,hranoly:hranolyContent,statistika:statistikaContent,procenta:procentaContent,slozene:slozeneContent};
 const tasks=topics.flatMap(topic=>Array.from({length:10},(_,index)=>{const order=index+1,content=contentByTopic[topic.id][index];return {id:`g8-${topic.id}-${String(order).padStart(2,'0')}`,grade:8,topicId:topic.id,topic:topic.name,topicOrder:order,difficulty:order<=3?'základní':order<=7?'střední':'vyšší',rewardId:topic.rewardId,available:true,missionIndex:null,title:content.title,content};}));
